// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _test(uint256 val1, uint256 val2) internal {
        try c.SetMinSum(val1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(val2) {} catch { return; }
        assertTrue(c.MinSum() == val1);
    }

    function testFuzz_test(uint256 val1, uint256 val2) public {
        _test(val1, val2);
    }

    receive() external payable {}
}
